/* Reset and base */
* { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-1: #1a1f2e;
  --bg-2: #2d3447;
  --card-bg: rgba(255, 255, 255, 0.05);
  --text: #ffffff;
  --text-muted: rgba(255, 255, 255, 0.6);
  --accent: #4a9eff;
}

html, body {
  height: 100%;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', sans-serif;
  color: var(--text);
  overflow: hidden;
}

body {
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, var(--bg-1), var(--bg-2));
  transition: background 1s ease;
}

/* Card */
.card {
  width: 720px;
  background: rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(40px);
  -webkit-backdrop-filter: blur(40px);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 24px;
  padding: 40px 48px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
}

/* Header */
.header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 32px;
}

.location {
  font-size: 28px;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.date {
  font-size: 14px;
  color: var(--text-muted);
  margin-top: 4px;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.weather-icon {
  font-size: 64px;
  line-height: 1;
}

/* Main temp */
.main-temp {
  display: flex;
  align-items: baseline;
  gap: 24px;
  margin-bottom: 8px;
}

.temp-max {
  font-size: 96px;
  font-weight: 200;
  letter-spacing: -0.04em;
  line-height: 1;
}

.temp-min {
  font-size: 32px;
  color: var(--text-muted);
  font-weight: 300;
}

.condition {
  font-size: 18px;
  color: var(--text-muted);
  margin-bottom: 40px;
}

/* Hourly */
.hourly-label {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--text-muted);
  margin-bottom: 16px;
}

.hourly {
  display: flex;
  gap: 4px;
  align-items: flex-end;
  height: 140px;
}

.hour {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  height: 100%;
  justify-content: flex-end;
}

.bar {
  width: 100%;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.4), rgba(255, 255, 255, 0.1));
  border-radius: 4px 4px 0 0;
  transition: all 0.3s;
  min-height: 2px;
  position: relative;
}

.bar:hover {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.6), rgba(255, 255, 255, 0.2));
}

.bar .tooltip {
  position: absolute;
  bottom: 100%;
  left: 50%;
  transform: translateX(-50%);
  background: rgba(0, 0, 0, 0.8);
  color: white;
  padding: 4px 8px;
  border-radius: 4px;
  font-size: 12px;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s;
  margin-bottom: 8px;
}

.bar:hover .tooltip {
  opacity: 1;
}

.hour-label {
  font-size: 11px;
  color: var(--text-muted);
  margin-top: 8px;
  font-variant-numeric: tabular-nums;
}

/* Loading & error */
.state {
  text-align: center;
  padding: 80px 20px;
}

.spinner {
  width: 40px;
  height: 40px;
  border: 3px solid rgba(255, 255, 255, 0.1);
  border-top-color: var(--accent);
  border-radius: 50%;
  animation: spin 1s linear infinite;
  margin: 0 auto 16px;
}

@keyframes spin { to { transform: rotate(360deg); } }

.error {
  color: #ff6b6b;
}

/* Background variants */
body.sunny { background: linear-gradient(135deg, #2980b9, #6dd5fa, #ffeaa7); }
body.cloudy { background: linear-gradient(135deg, #485461, #29323c); }
body.rainy { background: linear-gradient(135deg, #2c3e50, #4ca1af); }
body.snowy { background: linear-gradient(135deg, #83a4d4, #b6fbff); }
body.stormy { background: linear-gradient(135deg, #232526, #414345); }
body.foggy { background: linear-gradient(135deg, #606c88, #3f4c6b); }
body.clear-night { background: linear-gradient(135deg, #0f2027, #203a43, #2c5364); }

.fade-in { animation: fadeIn 0.6s ease-out; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

// Parse query params
const params = new URLSearchParams(window.location.search);
const lat = parseFloat(params.get('lat') || '52.52');
const lon = parseFloat(params.get('lon') || '13.405');
const name = params.get('name') || 'Berlin';

// Date today in UTC
const today = new Date();
const todayStr = today.toISOString().split('T')[0];
const date = params.get('date') || todayStr;

// Determine if date is in the past, today, or future
const isToday = date === todayStr;
const isFuture = date > todayStr;
const isPast = date < todayStr;

const endpoint = isPast ? '/api/om/archive' : '/api/om/forecast';

const url = `${endpoint}?latitude=${lat}&longitude=${lon}&daily=temperature_2m_max,temperature_2m_min,weather_code&hourly=temperature_2m&timezone=UTC&temperature_unit=celsius&start_date=${date}&end_date=${date}`;

// Weather code mapping
function getWeatherInfo(code) {
  const map = {
    0: { label: 'Clear sky', icon: '☀️', bg: 'sunny' },
    1: { label: 'Mainly clear', icon: '🌤️', bg: 'sunny' },
    2: { label: 'Partly cloudy', icon: '⛅', bg: 'cloudy' },
    3: { label: 'Overcast', icon: '☁️', bg: 'cloudy' },
    45: { label: 'Foggy', icon: '🌫️', bg: 'foggy' },
    48: { label: 'Depositing rime fog', icon: '🌫️', bg: 'foggy' },
    51: { label: 'Light drizzle', icon: '🌦️', bg: 'rainy' },
    53: { label: 'Moderate drizzle', icon: '🌦️', bg: 'rainy' },
    55: { label: 'Dense drizzle', icon: '🌧️', bg: 'rainy' },
    56: { label: 'Light freezing drizzle', icon: '🌧️', bg: 'rainy' },
    57: { label: 'Dense freezing drizzle', icon: '🌧️', bg: 'rainy' },
    61: { label: 'Slight rain', icon: '🌧️', bg: 'rainy' },
    63: { label: 'Moderate rain', icon: '🌧️', bg: 'rainy' },
    65: { label: 'Heavy rain', icon: '🌧️', bg: 'rainy' },
    66: { label: 'Light freezing rain', icon: '🌧️', bg: 'rainy' },
    67: { label: 'Heavy freezing rain', icon: '🌧️', bg: 'rainy' },
    71: { label: 'Slight snow', icon: '❄️', bg: 'snowy' },
    73: { label: 'Moderate snow', icon: '❄️', bg: 'snowy' },
    75: { label: 'Heavy snow', icon: '❄️', bg: 'snowy' },
    77: { label: 'Snow grains', icon: '❄️', bg: 'snowy' },
    80: { label: 'Slight rain showers', icon: '🌦️', bg: 'rainy' },
    81: { label: 'Moderate rain showers', icon: '🌦️', bg: 'rainy' },
    82: { label: 'Violent rain showers', icon: '🌧️', bg: 'rainy' },
    85: { label: 'Slight snow showers', icon: '🌨️', bg: 'snowy' },
    86: { label: 'Heavy snow showers', icon: '🌨️', bg: 'snowy' },
    95: { label: 'Thunderstorm', icon: '⛈️', bg: 'stormy' },
    96: { label: 'Thunderstorm with slight hail', icon: '⛈️', bg: 'stormy' },
    99: { label: 'Thunderstorm with heavy hail', icon: '⛈️', bg: 'stormy' }
  };
  return map[code] || { label: 'Unknown', icon: '🌡️', bg: 'cloudy' };
}

function formatDate(dateStr) {
  const d = new Date(dateStr + 'T00:00:00Z');
  return d.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', timeZone: 'UTC' });
}

function renderError() {
  document.getElementById('app').innerHTML = `
    <div class="card state fade-in">
      <div style="font-size: 48px; margin-bottom: 16px;">⚠️</div>
      <div class="error" style="font-size: 20px; margin-bottom: 8px;">Unable to load weather data</div>
      <div style="color: var(--text-muted); font-size: 14px;">Please try again later</div>
    </div>
  `;
}

function render(data) {
  const daily = data.daily;
  const hourly = data.hourly;

  // Find indices for the date
  const dateIdx = daily.time.indexOf(date);
  if (dateIdx === -1) {
    renderError();
    return;
  }

  const maxTemp = Math.round(daily.temperature_2m_max[dateIdx]);
  const minTemp = Math.round(daily.temperature_2m_min[dateIdx]);
  const code = daily.weather_code[dateIdx];
  const info = getWeatherInfo(code);

  // Filter hourly for this date
  const hours = [];
  for (let i = 0; i < hourly.time.length; i++) {
    if (hourly.time[i].startsWith(date)) {
      hours.push({
        time: hourly.time[i],
        temp: hourly.temperature_2m[i]
      });
    }
  }

  // Calculate min/max for chart scaling
  const temps = hours.map(h => h.temp);
  const tMin = Math.min(...temps);
  const tMax = Math.max(...temps);
  const range = tMax - tMin || 1;

  // Set body background
  document.body.className = info.bg;

  const currentHour = new Date().getUTCHours();

  const html = `
    <div class="card fade-in">
      <div class="header">
        <div>
          <div class="location">${name}</div>
          <div class="date">${formatDate(date)}</div>
        </div>
        <div class="weather-icon">${info.icon}</div>
      </div>

      <div class="main-temp">
        <div class="temp-max">${maxTemp}°</div>
        <div class="temp-min">${minTemp}°</div>
      </div>

      <div class="condition">${info.label}</div>

      <div class="hourly-label">Hourly temperature</div>
      <div class="hourly">
        ${hours.map(h => {
          const hourNum = parseInt(h.time.split('T')[1].split(':')[0]);
          const heightPct = ((h.temp - tMin) / range) * 80 + 10;
          const isCurrent = isToday && hourNum === currentHour;
          return `
            <div class="hour">
              <div class="bar" style="height: ${heightPct}%; ${isCurrent ? 'background: linear-gradient(180deg, var(--accent), rgba(74, 158, 255, 0.3));' : ''}">
                <div class="tooltip">${Math.round(h.temp)}°</div>
              </div>
              <div class="hour-label" style="${isCurrent ? 'color: var(--accent); font-weight: 600;' : ''}">${hourNum}</div>
            </div>
          `;
        }).join('')}
      </div>
    </div>
  `;

  document.getElementById('app').innerHTML = html;
}

fetch(url)
  .then(r => {
    if (!r.ok) throw new Error('Network response was not ok');
    return r.json();
  })
  .then(render)
  .catch(err => {
    console.error(err);
    renderError();
  });

