  80: { label: 'Slight rain showers', icon: '🌦️', bg: 'rainy' },
  81: { label: 'Moderate rain showers', icon: '🌦️', bg: 'rainy' },
  82: { label: 'Violent rain showers', icon: '🌧️', bg: 'rainy' },
  85: { label: 'Slight snow showers', icon: '🌨️', bg: 'snowy' },
  86: { label: 'Heavy snow showers', icon: '🌨️', bg: 'snowy' },
  95: { label: 'Thunderstorm', icon: '⛈️', bg: 'stormy' },
  96: { label: 'Thunderstorm with hail', icon: '⛈️', bg: 'stormy' },
  99: { label: 'Severe thunderstorm with hail', icon: '⛈️', bg: 'stormy' }
};

function getWeather(code) {
  return weatherCodes[code] || { label: 'Unknown conditions', icon: '🌡️', bg: 'cloudy' };
}

function formatDate(dateStr) {
  const d = new Date(dateStr + 'T00:00:00Z');
  const opts = { weekday: 'short', month: 'short', day: 'numeric', timeZone: 'UTC' };
  return d.toLocaleDateString('en-US', opts);
}

function showError() {
  document.body.className = '';
  document.getElementById('app').innerHTML = `
    <div class="card state fade-in">
      <div class="error-icon">⚠️</div>
      <div class="error-title">Unable to load weather data</div>
      <div class="error-sub">Please check the location and try again</div>
    </div>
  `;
}

function render(data) {
  if (!data || !data.daily || !data.hourly) {
    showError();
    return;
  }

  const daily = data.daily;
  const hourly = data.hourly;

  const dateIdx = daily.time.indexOf(date);
  if (dateIdx === -1) {
    showError();
    return;
  }

  const maxTemp = Math.round(daily.temperature_2m_max[dateIdx]);
  const minTemp = Math.round(daily.temperature_2m_min[dateIdx]);
  const code = daily.weather_code[dateIdx];
  const info = getWeather(code);

  // Filter hourly for this date
  const hours = [];
  for (let i = 0; i < hourly.time.length; i++) {
    if (hourly.time[i].startsWith(date)) {
      const hour = parseInt(hourly.time[i].slice(11, 13));
      hours.push({ hour, temp: hourly.temperature_2m[i] });
    }
  }

  if (hours.length === 0) {
    showError();
    return;
  }

  // Scale for bars
  const temps = hours.map(h => h.temp);
  const tMin = Math.min(...temps);
  const tMax = Math.max(...temps);
  const range = tMax - tMin;

  const currentHour = new Date().getUTCHours();
  const isToday = date === todayStr;

  document.body.className = info.bg;

  const html = `
    <div class="card fade-in">
      <div class="content">
        <div class="header">
          <div class="location-block">
            <div class="location">${escape(name)}</div>
            <div class="date">${formatDate(date)}</div>
          </div>
          <div class="weather-icon">${info.icon}</div>
        </div>

        <div class="temps">
          <div class="temp-max">${maxTemp}°</div>
          <div class="temp-min-block">
            <div class="temp-min-label">Min</div>
            <div class="temp-min">${minTemp}°</div>
          </div>
        </div>

        <div class="condition">${info.label}</div>

        <div class="hourly-section">
          <div class="hourly-header">
            <div class="hourly-label">Hourly temperature</div>
            <div class="hourly-range">${Math.round(tMin)}° – ${Math.round(tMax)}°</div>
          </div>

          <div class="hourly">
            ${hours.map(h => {
              const heightPct = range > 0 ? ((h.temp - tMin) / range) * 85 + 8 : 50;
              const isCurrent = isToday && h.hour === currentHour;
              return `
                <div class="hour">
                  <div class="bar ${isCurrent ? 'current' : ''}" style="height: ${heightPct}%;">
                    <div class="tooltip">${h.hour.toString().padStart(2, '0')}:00 · ${Math.round(h.temp)}°</div>
                  </div>
                </div>
              `;
            }).join('')}
          </div>

          <div class="hour-labels">
            ${hours.map(h => {
              const isCurrent = isToday && h.hour === currentHour;
              const showLabel = h.hour % 3 === 0 || h.hour === 23 || isCurrent;
              return `<div class="hour-label ${isCurrent ? 'current' : ''}">${showLabel ? h.hour.toString().padStart(2, '0') : ''}</div>`;
            }).join('')}
          </div>
        </div>
      </div>
    </div>
  `;

  document.getElementById('app').innerHTML = html;
}

function escape(s) {
  return String(s).replace(/[&<>"']/g, c => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  }[c]));
}

fetch(url)
  .then(r => {
    if (!r.ok) throw new Error(r.statusText);
    return r.json();
  })
  .then(render)
  .catch(showError);

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html, body {
  height: 100%;
  overflow: hidden;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Inter', 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  color: #fff;
  background: linear-gradient(135deg, #0a0e27 0%, #1a1f3a 50%, #2d1b4e 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 1.2s cubic-bezier(0.4, 0, 0.2, 1);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.card {
  width: 760px;
  background: rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(40px) saturate(180%);
  -webkit-backdrop-filter: blur(40px) saturate(180%);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 28px;
  padding: 48px 56px;
  box-shadow: 
    0 30px 80px rgba(0, 0, 0, 0.4),
    inset 0 1px 0 rgba(255, 255, 255, 0.12);
  position: relative;
  overflow: hidden;
}

.card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.4), transparent);
}

/* Header */
.header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 36px;
}

.location {
  font-size: 36px;
  font-weight: 600;
  letter-spacing: -0.03em;
  line-height: 1;
}

.date {
  font-size: 12px;
  color: rgba(255, 255, 255, 0.5);
  text-transform: uppercase;
  letter-spacing: 0.2em;
  font-weight: 500;
  margin-top: 10px;
}

.weather-icon {
  font-size: 72px;
  line-height: 1;
  filter: drop-shadow(0 6px 24px rgba(0, 0, 0, 0.25));
}

/* Temperatures */
.temps {
  display: flex;
  align-items: flex-start;
  gap: 36px;
  margin-bottom: 14px;
}

.temp-max {
  font-size: 108px;
  font-weight: 200;
  letter-spacing: -0.05em;
  line-height: 0.9;
  font-variant-numeric: tabular-nums;
}

.temp-min-block {
  padding-top: 14px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.temp-min-label {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: rgba(255, 255, 255, 0.45);
  font-weight: 600;
}

.temp-min {
  font-size: 36px;
  font-weight: 300;
  color: rgba(255, 255, 255, 0.7);
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.02em;
}

.condition {
  font-size: 20px;
  color: rgba(255, 255, 255, 0.85);
  font-weight: 400;
  margin-bottom: 48px;
}

/* Hourly */
.hourly-section {
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  padding-top: 24px;
}

.hourly-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 20px;
}

.hourly-label {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.22em;
  color: rgba(255, 255, 255, 0.5);
  font-weight: 600;
}

.hourly-range {
  font-size: 12px;
  color: rgba(255, 255, 255, 0.4);
  font-variant-numeric: tabular-nums;
  font-weight: 500;
}

.hourly {
  display: flex;
  gap: 3px;
  height: 96px;
  align-items: flex-end;
}

.hour {
  flex: 1;
  height: 100%;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}

.bar {
  width: 100%;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.22), rgba(255, 255, 255, 0.06));
  border-radius: 3px 3px 0 0;
  transition: all 0.2s;
  min-height: 2px;
  position: relative;
  cursor: default;
}

.bar:hover {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.45), rgba(255, 255, 255, 0.12));
}

.bar.current {
  background: linear-gradient(180deg, #ffffff, rgba(255, 255, 255, 0.5));
  box-shadow: 0 0 16px rgba(255, 255, 255, 0.25);
}

.bar .tooltip {
  position: absolute;
  bottom: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%);
  background: rgba(0, 0, 0, 0.9);
  color: #fff;
  padding: 5px 9px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.15s;
  font-variant-numeric: tabular-nums;
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.bar:hover .tooltip {
  opacity: 1;
}

.hour-labels {
  display: flex;
  gap: 3px;
  margin-top: 10px;
}

.hour-label {
  flex: 1;
  text-align: center;
  font-size: 10px;
  color: rgba(255, 255, 255, 0.35);
  font-variant-numeric: tabular-nums;
  font-weight: 500;
  letter-spacing: 0.05em;
}

.hour-label.current {
  color: #fff;
  font-weight: 700;
}

/* States */
.state-wrap {
  width: 760px;
  padding: 80px 20px;
  text-align: center;
}

.state-card {
  background: rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(40px) saturate(180%);
  -webkit-backdrop-filter: blur(40px) saturate(180%);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 28px;
  padding: 80px 40px;
}

.spinner {
  width: 36px;
  height: 36px;
  border: 2px solid rgba(255, 255, 255, 0.1);
  border-top-color: rgba(255, 255, 255, 0.7);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
  margin: 0 auto 24px;
}

@keyframes spin { to { transform: rotate(360deg); } }

.state-text {
  font-size: 14px;
  color: rgba(255, 255, 255, 0.6);
  font-weight: 500;
  letter-spacing: 0.05em;
}

.error-icon {
  font-size: 56px;
  margin-bottom: 20px;
  filter: drop-shadow(0 4px 16px rgba(0, 0, 0, 0.3));
}

.error-title {
  font-size: 22px;
  font-weight: 500;
  margin-bottom: 8px;
  letter-spacing: -0.01em;
}

.error-sub {
  font-size: 13px;
  color: rgba(255, 255, 255, 0.5);
}

/* Backgrounds */
body.sunny { background: linear-gradient(135deg, #1e3c72 0%, #2a5298 50%, #5a7ba8 100%); }
body.cloudy { background: linear-gradient(135deg, #485563 0%, #29323c 100%); }
body.rainy { background: linear-gradient(135deg, #0f2027 0%, #203a43 50%, #2c5364 100%); }
body.snowy { background: linear-gradient(135deg, #1f3a5f 0%, #4a6fa5 50%, #7a9bc4 100%); }
body.stormy { background: linear-gradient(135deg, #141e30 0%, #243b55 100%); }
body.foggy { background: linear-gradient(135deg, #3a4a5e 0%, #5a6b7e 100%); }
body.night { background: linear-gradient(135deg, #0f0c29 0%, #302b63 50%, #24243e 100%); }

.fade-in { animation: fadeIn 0.6s cubic-bezier(0.2, 0.8, 0.2, 1); }
@keyframes fadeIn { 
  from { opacity: 0; transform: translateY(12px); } 
  to { opacity: 1; transform: translateY(0); } 
}

(function() {
  const params = new URLSearchParams(window.location.search);
  const lat = params.get('lat') || '52.52';
  const lon = params.get('lon') || '13.405';
  const name = params.get('name') || 'Berlin';

  const today = new Date();
  const todayStr = today.toISOString().slice(0, 10);
  const date = params.get('date') || todayStr;

  const isPast = date < todayStr;
  const endpoint = isPast ? '/api/om/archive' : '/api/om/forecast';

  const url = `${endpoint}?latitude=${lat}&longitude=${lon}&daily=temperature_2m_max,temperature_2m_min,weather_code&hourly=temperature_2m&timezone=UTC&temperature_unit=celsius&start_date=${date}&end_date=${date}`;

  const codes = {
    0: ['Clear sky', '☀️', 'sunny'],
    1: ['Mainly clear', '🌤️', 'sunny'],
    2: ['Partly cloudy', '⛅', 'cloudy'],
    3: ['Overcast', '☁️', 'cloudy'],
    45: ['Foggy', '🌫️', 'foggy'],
    48: ['Rime fog', '🌫️', 'foggy'],
    51: ['Light drizzle', '🌦️', 'rainy'],
    53: ['Moderate drizzle', '🌦️', 'rainy'],
    55: ['Dense drizzle', '🌧️', 'rainy'],
    56: ['Light freezing drizzle', '🌧️', 'rainy'],
    57: ['Dense freezing drizzle', '🌧️', 'rainy'],
    61: ['Slight rain', '🌧️', 'rainy'],
    63: ['Moderate rain', '🌧️', 'rainy'],
    65: ['Heavy rain', '🌧️', 'rainy'],
    66: ['Light freezing rain', '🌧️', 'rainy'],
    67: ['Heavy freezing rain', '🌧️', 'rainy'],
    71: ['Slight snowfall', '🌨️', 'snowy'],
    73: ['Moderate snowfall', '🌨️', 'snowy'],
    75: ['Heavy snowfall', '❄️', 'snowy'],
    77: ['Snow grains', '❄️', 'snowy'],
    80: ['Slight rain showers', '🌦️', 'rainy'],
    81: ['Moderate rain showers', '🌦️', 'rainy'],
    82: ['Violent rain showers', '🌧️', 'rainy'],
    85: ['Slight snow showers', '🌨️', 'snowy'],
    86: ['Heavy snow showers', '🌨️', 'snowy'],
    95: ['Thunderstorm', '⛈️', 'stormy'],
    96: ['Thunderstorm with hail', '⛈️', 'stormy'],
    99: ['Severe thunderstorm with hail', '⛈️', 'stormy']
  };

  function escape(s) {
    return String(s).replace(/[&<>"']/g, c => 
      ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])
    );
  }

  function formatDate(dateStr) {
    const d = new Date(dateStr + 'T00:00:00Z');
    return d.toLocaleDateString('en-US', { 
      weekday: 'short', 
      month: 'short', 
      day: 'numeric',
      timeZone: 'UTC'
    });
  }

  function showError() {
    document.body.className = '';
    document.getElementById('app').innerHTML = `
      <div class="state-card fade-in">
        <div class="error-icon">⚠️</div>
        <div class="error-title">Unable to load weather data</div>
        <div class="error-sub">The request could not be completed</div>
      </div>
    `;
  }

  function showLoading() {
    document.getElementById('app').innerHTML = `
      <div class="state-card">
        <div class="spinner"></div>
        <div class="state-text">Loading weather…</div>
      </div>
    `;
  }

  function render(data) {
    if (!data || !data.daily || !data.hourly) {
      showError();
      return;
    }

    const daily = data.daily;
    const hourly = data.hourly;

    const dateIdx = daily.time.indexOf(date);
    if (dateIdx === -1) {
      showError();
      return;
    }

    const maxTemp = Math.round(daily.temperature_2m_max[dateIdx]);
    const minTemp = Math.round(daily.temperature_2m_min[dateIdx]);
    const code = daily.weather_code[dateIdx];
    const info = codes[code] || ['Unknown conditions', '🌡️', 'cloudy'];

    const hours = [];
    for (let i = 0; i < hourly.time.length; i++) {
      if (hourly.time[i].startsWith(date)) {
        const h = parseInt(hourly.time[i].slice(11, 13));
        hours.push({ hour: h, temp: hourly.temperature_2m[i] });
      }
    }

    if (hours.length === 0) {
      showError();
      return;
    }

    const temps = hours.map(h => h.temp);
    const tMin = Math.min(...temps);
    const tMax = Math.max(...temps);
    const range = tMax - tMin;

    const currentHour = new Date().getUTCHours();
    const isToday = date === todayStr;

    document.body.className = info[2];

    const hoursHtml = hours.map(h => {
      const heightPct = range > 0 ? ((h.temp - tMin) / range) * 85 + 8 : 50;
      const isCurrent = isToday && h.hour === currentHour;
      return `
        <div class="hour">
          <div class="bar ${isCurrent ? 'current' : ''}" style="height: ${heightPct}%;">
            <div class="tooltip">${String(h.hour).padStart(2, '0')}:00 · ${Math.round(h.temp)}°</div>
          </div>
        </div>
      `;
    }).join('');

    const labelsHtml = hours.map(h => {
      const isCurrent = isToday && h.hour === currentHour;
      const show = h.hour % 3 === 0 || h.hour === 23 || isCurrent;
      return `<div class="hour-label ${isCurrent ? 'current' : ''}">${show ? String(h.hour).padStart(2, '0') : ''}</div>`;
    }).join('');

    document.getElementById('app').innerHTML = `
      <div class="card fade-in">
        <div class="header">
          <div>
            <div class="location">${escape(name)}</div>
            <div class="date">${formatDate(date)}</div>
          </div>
          <div class="weather-icon">${info[1]}</div>
        </div>

        <div class="temps">
          <div class="temp-max">${maxTemp}°</div>
          <div class="temp-min-block">
            <div class="temp-min-label">Min</div>
            <div class="temp-min">${minTemp}°</div>
          </div>
        </div>

        <div class="condition">${info[0]}</div>

        <div class="hourly-section">
          <div class="hourly-header">
            <div class="hourly-label">Hourly temperature</div>
            <div class="hourly-range">${Math.round(tMin)}° — ${Math.round(tMax)}°</div>
          </div>

          <div class="hourly">${hoursHtml}</div>
          <div class="hour-labels">${labelsHtml}</div>
        </div>
      </div>
    `;
  }

  showLoading();

  fetch(url)
    .then(r => {
      if (!r.ok) throw new Error('Network response failed');
      return r.json();
    })
    .then(render)
    .catch(showError);
})();

