.hour-label.current {
  color: #fff;
  font-weight: 700;
}

.state-center { text-align: center; }

.spinner {
  width: 36px; height: 36px;
  border: 2px solid rgba(255, 255, 255, 0.1);
  border-top-color: rgba(255, 255, 255, 0.75);
  border-radius: 50%;
  animation: spin 0.8s linear infinite;
  margin: 0 auto 24px;
}

@keyframes spin { to { transform: rotate(360deg); } }

.state-text {
  font-size: 14px;
  color: rgba(255, 255, 255, 0.6);
  font-weight: 500;
  letter-spacing: 0.05em;
}

.error-icon {
  font-size: 56px;
  margin-bottom: 20px;
  filter: drop-shadow(0 4px 16px rgba(0, 0, 0, 0.3));
}

.error-title {
  font-size: 22px;
  font-weight: 500;
  margin-bottom: 8px;
  letter-spacing: -0.01em;
}

.error-sub {
  font-size: 13px;
  color: rgba(255, 255, 255, 0.5);
}

body.sunny   { background: linear-gradient(135deg, #1e3c72 0%, #2a5298 50%, #5a7ba8 100%); }
body.cloudy  { background: linear-gradient(135deg, #485563 0%, #29323c 100%); }
body.rainy   { background: linear-gradient(135deg, #0f2027 0%, #203a43 50%, #2c5364 100%); }
body.snowy   { background: linear-gradient(135deg, #1f3a5f 0%, #4a6fa5 50%, #7a9bc4 100%); }
body.stormy  { background: linear-gradient(135deg, #0a0e27 0%, #141e30 50%, #243b55 100%); }
body.foggy   { background: linear-gradient(135deg, #3a4a5e 0%, #5a6b7e 100%); }
body.night   { background: linear-gradient(135deg, #0f0c29 0%, #302b63 50%, #24243e 100%); }

.fade-in { animation: fadeIn 0.6s cubic-bezier(0.2, 0.8, 0.2, 1); }
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(12px); }
  to   { opacity: 1; transform: translateY(0); }
}

(function() {
  const params = new URLSearchParams(window.location.search);
  const lat  = params.get('lat')  || '52.52';
  const lon  = params.get('lon')  || '13.405';
  const name = params.get('name') || 'Berlin';

  const today = new Date();
  const todayStr = today.toISOString().slice(0, 10);
  const date = params.get('date') || todayStr;

  const isPast = date < todayStr;
  const endpoint = isPast ? '/api/om/archive' : '/api/om/forecast';

  const url =
    `${endpoint}?latitude=${lat}&longitude=${lon}` +
    `&daily=temperature_2m_max,temperature_2m_min,weather_code` +
    `&hourly=temperature_2m` +
    `&timezone=UTC&temperature_unit=celsius` +
    `&start_date=${date}&end_date=${date}`;

  const codes = {
    0:  ['Clear sky',                   '☀️',  'sunny'],
    1:  ['Mainly clear',                '🌤️', 'sunny'],
    2:  ['Partly cloudy',               '⛅',  'cloudy'],
    3:  ['Overcast',                    '☁️',  'cloudy'],
    45: ['Foggy',                       '🌫️', 'foggy'],
    48: ['Depositing rime fog',         '🌫️', 'foggy'],
    51: ['Light drizzle',               '🌦️', 'rainy'],
    53: ['Moderate drizzle',            '🌦️', 'rainy'],
    55: ['Dense drizzle',               '🌧️', 'rainy'],
    56: ['Light freezing drizzle',      '🌧️', 'rainy'],
    57: ['Dense freezing drizzle',      '🌧️', 'rainy'],
    61: ['Slight rain',                 '🌧️', 'rainy'],
    63: ['Moderate rain',               '🌧️', 'rainy'],
    65: ['Heavy rain',                  '🌧️', 'rainy'],
    66: ['Light freezing rain',         '🌧️', 'rainy'],
    67: ['Heavy freezing rain',         '🌧️', 'rainy'],
    71: ['Slight snowfall',             '🌨️', 'snowy'],
    73: ['Moderate snowfall',           '🌨️', 'snowy'],
    75: ['Heavy snowfall',              '❄️',  'snowy'],
    77: ['Snow grains',                 '❄️',  'snowy'],
    80: ['Slight rain showers',         '🌦️', 'rainy'],
    81: ['Moderate rain showers',       '🌦️', 'rainy'],
    82: ['Violent rain showers',        '🌧️', 'rainy'],
    85: ['Slight snow showers',         '🌨️', 'snowy'],
    86: ['Heavy snow showers',          '🌨️', 'snowy'],
    95: ['Thunderstorm',                '⛈️', 'stormy'],
    96: ['Thunderstorm with hail',      '⛈️', 'stormy'],
    99: ['Severe thunderstorm with hail','⛈️','stormy']
  };

  function escapeHTML(s) {
    return String(s).replace(/[&<>"']/g, c =>
      ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])
    );
  }

  function formatDate(d) {
    const dt = new Date(d + 'T00:00:00Z');
    return dt.toLocaleDateString('en-US', {
      weekday: 'short', month: 'short', day: 'numeric', timeZone: 'UTC'
    });
  }

  function pad2(n) { return String(n).padStart(2, '0'); }

  function showError() {
    document.body.className = '';
    document.getElementById('app').innerHTML =
      '<div class="card state-center fade-in" style="padding: 80px 56px;">' +
        '<div class="error-icon">⚠️</div>' +
        '<div class="error-title">Unable to load weather data</div>' +
        '<div class="error-sub">The request could not be completed</div>' +
      '</div>';
  }

  function showLoading() {
    document.getElementById('app').innerHTML =
      '<div class="card state-center" style="padding: 80px 56px;">' +
        '<div class="spinner"></div>' +
        '<div class="state-text">Loading weather…</div>' +
      '</div>';
  }

  function render(data) {
    if (!data || !data.daily || !data.hourly) { showError(); return; }

    const daily = data.daily, hourly = data.hourly;
    const idx = daily.time.indexOf(date);
    if (idx === -1) { showError(); return; }

    const maxT = Math.round(daily.temperature_2m_max[idx]);
    const minT = Math.round(daily.temperature_2m_min[idx]);
    const info = codes[daily.weather_code[idx]] || ['Unknown conditions', '🌡️', 'cloudy'];

    const hours = [];
    for (let i = 0; i < hourly.time.length; i++) {
      if (hourly.time[i].startsWith(date)) {
        hours.push({
          h: parseInt(hourly.time[i].slice(11, 13), 10),
          t: hourly.temperature_2m[i]
        });
      }
    }
    if (!hours.length) { showError(); return; }

    const temps = hours.map(x => x.t);
    const tMin = Math.min.apply(null, temps);
    const tMax = Math.max.apply(null, temps);
    const range = tMax - tMin;

    const currentHour = new Date().getUTCHours();
    const isToday = date === todayStr;
    document.body.className = info[2];

    const bars = hours.map(x => {
      const pct = range > 0 ? ((x.t - tMin) / range) * 84 + 8 : 50;
      const cur = isToday && x.h === currentHour;
      const cls = cur ? ' bar current' : ' bar';
      return '<div class="hour"><div class="' + cls.trim() + '" style="height:' + pct + '%;">' +
        '<div class="tooltip">' + pad2(x.h) + ':00 · ' + Math.round(x.t) + '°</div>' +
      '</div></div>';
    }).join('');

    const labels = hours.map(x => {
      const cur = isToday && x.h === currentHour;
      const show = x.h % 3 === 0 || x.h === 23 || cur;
      return '<div class="hour-label' + (cur ? ' current' : '') + '">' +
        (show ? pad2(x.h) : '') + '</div>';
    }).join('');

    document.getElementById('app').innerHTML =
      '<div class="card fade-in"><div class="content">' +
        '<div class="header">' +
          '<div class="location-block">' +
            '<div class="location">' + escapeHTML(name) + '</div>' +
            '<div class="date">' + formatDate(date) + '</div>' +
          '</div>' +
          '<div class="weather-icon">' + info[1] + '</div>' +
        '</div>' +
        '<div class="temps">' +
          '<div class="temp-max">' + maxT + '°</div>' +
          '<div class="temp-min-block">' +
            '<div class="temp-min-label">Min</div>' +
            '<div class="temp-min">' + minT + '°</div>' +
          '</div>' +
        '</div>' +
        '<div class="condition">' + info[0] + '</div>' +
        '<div class="hourly-section">' +
          '<div class="hourly-header">' +
            '<div class="hourly-label">Hourly temperature</div>' +
            '<div class="hourly-range">' + Math.round(tMin) + '° — ' + Math.round(tMax) + '°</div>' +
          '</div>' +
          '<div class="hourly">' + bars + '</div>' +
          '<div class="hour-labels">' + labels + '</div>' +
        '</div>' +
      '</div></div>';
  }

  showLoading();

  fetch(url)
    .then(function(r) {
      if (!r.ok) throw new Error('Network response failed');
      return r.json();
    })
    .then(render)
    .catch(showError);
})();
